INSERT INTO material_translations (material_id, locale, title, description, body) VALUES ('a1000000-0000-4000-8000-000000000008','ro','Dinamica litosferei — galerie foto','Galerie foto pentru lecția Dinamica litosferei: plăci tectonice, vulcanism, seisme.','{"captions":["Plăcile tectonice ale litosferei","Harta principalelor plăci tectonice","Contact divergent: rift continental și rift oceanic","Contacte convergente: subducție și coliziune","Zonă de subducție, fosă oceanică și dorsală medio-oceanică","Riftul Est-African și riftul Mării Roșii","Fose oceanice în Oceanul Pacific","Cercul de Foc al Pacificului","Coliziunea plăcilor și înălțarea Munților Himalaya","Vulcanism de tip hot-spot (punct fierbinte)","Hot-spot: arhipelagul Hawaii și vârsta insulelor","Deriva continentelor, de la Pangaea până astăzi","Scara geocronologică (evoluția Terrei)","Aparatul vulcanic și corpurile magmatice (batolit, sill, dyke)","Tipuri de erupții vulcanice","Elementele unui cutremur: hipocentru și epicentru","Tipuri de unde seismice (P, S, Love, Rayleigh)","Tectonica plăcilor în România","Relieful oceanic: platformă, abrupt, câmpie abisală, dorsală, fosă"]}');
